/**
 * Hero-vs-hero baselines from professional matches (data/matchups.json,
 * regenerated by scripts/coach-matchups.mjs). Pure lookups: the engine
 * never fetches.
 *
 * Every verdict carries its sample size, and none is made on noise:
 * - a lane matchup is "favoured"/"unfavoured" only with 20+ games and a
 *   mean 10:00 gold gap of at least 150 and at least two standard errors;
 * - a hero matchup is only with 30+ games and a win rate at least two
 *   standard errors from the hero's own pro win rate.
 * Anything else is "even" (enough games, no real gap) or null (too few).
 *
 * Kept out of goals.js / knowledge.js on purpose: the web client bundles
 * those, and this table is server-side data.
 */
import { createRequire } from 'node:module';

const M = createRequire(import.meta.url)('./data/matchups.json');

export const MATCHUP_SOURCE = Object.freeze({ since: M.since, patch: M.patch, games: M.games, fetched: M.fetched });

const LANE_MIN = 20;
const LANE_MIN_GAP = 150;
const VS_MIN = 30;

/**
 * h's lane core against v's lane core, gold at 10:00 (h minus v).
 * @returns {null | { n: number, mean: number, p25: number, p75: number, ahead: number, sd: number, verdict: 'favoured'|'unfavoured'|'even' }}
 */
export function laneMatchup(h, v) {
  const row = M.lane?.[h]?.[v];
  if (!row) return null;
  const [n, mean, p25, p75, aheadN, sd] = row;
  if (n < LANE_MIN) return null;
  const se = sd / Math.sqrt(n);
  const real = Math.abs(mean) >= LANE_MIN_GAP && Math.abs(mean) >= 2 * se;
  return { n, mean, p25, p75, ahead: aheadN / n, sd, verdict: real ? (mean > 0 ? 'favoured' : 'unfavoured') : 'even' };
}

/** Where one game's lane gap sits against the pro games of the same matchup. */
export function laneStanding(actual, lm) {
  if (!lm || !Number.isFinite(actual)) return null;
  if (actual < lm.p25) return 'worse';
  if (actual > lm.p75) return 'better';
  return 'typical';
}

/**
 * h's win rate with v on the enemy team, against h's own pro win rate.
 * @returns {null | { n: number, wr: number, base: number, diff: number, verdict: 'favoured'|'unfavoured'|'even' }}
 */
export function heroVs(h, v) {
  const row = M.vs?.[h]?.[v];
  const b = M.base?.[h];
  if (!row || !b || row[0] < VS_MIN || !b[0]) return null;
  const [n, w] = row;
  const wr = w / n;
  const base = b[1] / b[0];
  const se = Math.sqrt((base * (1 - base)) / n);
  const diff = wr - base;
  return { n, wr, base, diff, verdict: Math.abs(diff) >= 2 * se ? (diff > 0 ? 'favoured' : 'unfavoured') : 'even' };
}

const g10 = (p, key) => {
  const a = p?.raw?.[key];
  return Array.isArray(a) && a.length > 10 && Number.isFinite(a[10]) ? a[10] : null;
};
/** A lane's core: the laner with the most last hits at 10:00 (same rule as the snapshot). */
function laneCore(xs) {
  const known = xs.filter((p) => g10(p, 'lh_t') != null && g10(p, 'gold_t') != null);
  return known.length ? known.reduce((b, p) => (g10(p, 'lh_t') > g10(b, 'lh_t') ? p : b), known[0]) : null;
}

/**
 * One lane in this game against the pro baseline for the same core matchup.
 * `us` / `them` are report players in that lane (with `raw` and `hero`).
 * @returns {null | { core: object, vs: object, actual: number, standing: 'worse'|'typical'|'better', lm: ReturnType<typeof laneMatchup> }}
 */
export function laneBaseline(us, them) {
  const core = laneCore(us);
  const vs = laneCore(them);
  if (!core || !vs) return null;
  const lm = laneMatchup(core.hero.id, vs.hero.id);
  if (!lm) return null;
  const actual = g10(core, 'gold_t') - g10(vs, 'gold_t');
  return { core, vs, actual, standing: laneStanding(actual, lm), lm };
}

const k = (n) => (Math.abs(n) >= 1000 ? `${(Math.abs(n) / 1000).toFixed(1)}k` : String(Math.round(Math.abs(n))));
const pctS = (x) => `${Math.round(x * 100)}%`;
const STANDING = {
  worse: { en: 'worse than three in four pro games of this matchup', zh: '比四分之三的职业同对位对局都差' },
  typical: { en: 'within the usual range of pro games of this matchup', zh: '在职业同对位对局的常见范围内' },
  better: { en: 'better than three in four pro games of this matchup', zh: '好于四分之三的职业同对位对局' },
};

/** The baseline as one evidence line (bilingual), naming source and sample. */
export function baselineLine(b) {
  const { core, vs, actual, standing, lm } = b;
  const sign = (n) => (n >= 0 ? '+' : '−');
  return {
    en: `Pro games since ${M.since} (${lm.n}), ${core.hero.en} core vs ${vs.hero.en} core: ${sign(lm.mean)}${k(lm.mean)} gold at 10:00 on average, ${core.hero.en} ahead in ${pctS(lm.ahead)}. This game: ${sign(actual)}${k(actual)} — ${STANDING[standing].en}`,
    zh: `职业比赛（${M.since} 以来 ${lm.n} 场）${core.hero.zh}对${vs.hero.zh}的线：10 分钟平均${lm.mean >= 0 ? '领先' : '落后'} ${k(lm.mean)}，${core.hero.zh}领先的占 ${pctS(lm.ahead)}。这局 ${sign(actual)}${k(actual)}——${STANDING[standing].zh}`,
  };
}

const IV = createRequire(import.meta.url)('./data/item-vs.json');
const ITEM_NAMES = createRequire(import.meta.url)('./data/names.json').items;

export const ITEM_VS_SOURCE = Object.freeze({ since: IV.since, fetched: IV.fetched, rule: IV.rule });

/**
 * Finished items pros on hero h buy clearly more often with v on the enemy
 * team (data/item-vs.json): association, not proof that the item wins it.
 * Items Valve no longer lists are dropped.
 * @returns {{ key: string, rate: number, base: number, n: number }[]}
 */
export function itemLifts(h, v) {
  const list = IV.item_vs?.[h]?.[v];
  if (!Array.isArray(list)) return [];
  return list.filter(([key]) => ITEM_NAMES[key]).map(([key, rate, base, n]) => ({ key, rate, base, n }));
}

/** "Pro Tidehunter against Ursa (98 games): 37% built Eul's Scepter (8% usually)" — bilingual, from itemLifts. */
export function proItemsLine(hero, vs, lifts) {
  if (!lifts.length) return null;
  const n = lifts[0].n;
  const name = (k, lang) => ITEM_NAMES[k]?.[lang] ?? k;
  return {
    en: `Pro ${hero.en} against ${vs.en} (${n} games since ${IV.since}): ${lifts.map((x) => `${pctS(x.rate)} built ${name(x.key, 'en')} (${pctS(x.base)} usually)`).join(', ')}`,
    zh: `职业比赛里${hero.zh}对上${vs.zh}（${IV.since} 以来 ${n} 场）：${lifts.map((x) => `${pctS(x.rate)} 出了${name(x.key, 'zh')}（平时 ${pctS(x.base)}）`).join('，')}`,
  };
}

/**
 * Curated answers re-ordered by pro evidence: answers pros on hero h buy
 * measurably more often against any of `vsHeroes` first (with that lift),
 * the rest in their curated order. Never adds an item that is not an answer.
 * @param {number} h
 * @param {{ id: number }[]} vsHeroes
 * @param {string[]} answers
 */
export function answersByPro(h, vsHeroes, answers) {
  const lifted = new Map();
  for (const v of vsHeroes) {
    for (const x of itemLifts(h, v.id)) if (answers.includes(x.key) && !lifted.has(x.key)) lifted.set(x.key, { ...x, vs: v });
  }
  return { ordered: [...lifted.keys(), ...answers.filter((a) => !lifted.has(a))], lifted };
}
